/* engines/wavesurfer.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  async function createWaveSurfer(url, startAt, autoplay) {
    try { await P.loadWaveSurferScript(); } catch {
      P.fallbackToHtml5();
      return false;
    }
    if (!window.WaveSurfer) { P.fallbackToHtml5(); return false; }

    P.showWaveMode();
    // WaveSurfer has no built-in "double click toggles playback" behaviour.
    P.waveform.addEventListener("dblclick", P.handleWaveDoubleClick);
    const colors = P.waveformColors();

    P.waveSurfer = window.WaveSurfer.create({
      container: P.waveform,
      media: P.audio,
      url,
      height: 56,
      barWidth: 2,
      barGap: 1,
      barRadius: 1,
      normalize: true,
      interact: true,
      dragToSeek: true,
      cursorWidth: 1,
      cursorColor: colors.cursorColor,
      waveColor: colors.waveColor,
      progressColor: colors.progressColor,
    });

    // WaveSurfer reports 0..1 while it fetches/decodes the waveform — use it
    // for the percentage instead of the element's buffered ranges.
    P.waveSurfer.on("loading", (progress) => {
      const fraction = Number(progress);
      if (Number.isFinite(fraction)) P.setLoadingProgress(fraction <= 1 ? fraction * 100 : fraction);
    });
    P.waveSurfer.on("ready", () => {
      P.finishLoading();
      if (startAt) P.setTime(startAt);
      if (autoplay) P.attemptPlay();
    });
    // WaveSurfer v7 seeks on click/drag itself; mirroring the interaction event
    // onto the shared <audio> guarantees scrubbing with the cursor works even
    // when an external media element is used.
    P.waveSurfer.on("interaction", (seconds) => {
      if (Number.isFinite(seconds)) {
        P.introUserSeeked = true;
        P.setTime(seconds);
      }
    });
    // "ended" on the shared <audio> covers track completion; no need to
    // also handle WaveSurfer's "finish" (that would advance twice).
    P.waveSurfer.on("error", () => {
      P.fallbackToHtml5();
      P.notify("engine");
    });
    return true;
  }
  Object.assign(P, { createWaveSurfer });
}
